VALUES ('cadf0495-b2d8-48d9-a362-af43c95034e7', E'クラスとオブジェクト', E'クラス定義、インスタンス生成、継承、ポリモーフィズム、インタフェースの基本を理解し実務で使いこなす。', 'core_programming', 'java', 'intermediate', TRUE, 20)
