VALUES ('27ddfa79-9509-4370-ac14-eae89e17845e', 'f677bb64-e653-48f6-a905-ea86a90c2208', 'multiple_choice', E'ジェネリクスの型パラメータに使用できるのはどれか？', E'型パラメータには参照型のみ指定可能であり、プリミティブ型（int, double, boolean 等）は使用できない。ラッパー型である Integer を使用する。 (Evidence: E7)', 10, 1, 'easy')
